#include <queue>
#include <limits>
using namespace std;
vector<int> dijkstra(vector<vector<pair<int, int>>>& graph, int start) {
    int n = graph.size();
    vector<int> dist(n, numeric_limits<int>::max());
    dist[start] = 0;
    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;
    pq.push({0, start});
    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (d > dist[u]) continue;
        for (auto& [v, w] : graph[u]) {
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                pq.push({dist[v], v});
            }
        }
    }
    return dist;
}
int main() {
    vector<vector<pair<int, int>>> graph = {{{1, 2}, {2, 4}}, {{2, 1}, {3, 7}}, {{3, 3}}, {}};
    auto dist = dijkstra(graph, 0);
    for (int d : dist) cout << d << " ";
    cout << endl;
    return 0;
}

