class BankAccount {
private:
    string id;
    double balance;
public:
    BankAccount(string id, double initial) : id(id), balance(initial) {
        if (initial < 0) throw invalid_argument("初始余额不能为负");
    }
    bool deposit(double amount) {
        if (amount <= 0) return false;
        balance += amount;
        return true;
    }
    bool withdraw(double amount) {
        if (amount <= 0 || amount > balance) return false;
        balance -= amount;
        return true;
    }
    double getBalance() const { return balance; }
};
int main() {
    BankAccount acc("001", 1000);
    acc.deposit(500);
    acc.withdraw(200);
    cout << "余额: " << acc.getBalance() << endl;
    return 0;
}

